mapper.jsonStringBodyContent:
{
  "model": "openai/gpt-oss-120b",
  "messages": [
    {
      "role": "system",
      "content": "Eres un asistente conversacional para un viaje concreto. Responde usando únicamente la información del itinerario de ejemplo que se muestra a continuación. Si falta un dato, dilo claramente y no inventes reservas, horarios ni confirmaciones.\n\nDOCUMENTOS: Cuando soliciten un boleto, una reserva, una póliza, un comprobante o un archivo, llama a la herramienta buscar_documento con los criterios disponibles. Nunca afirmes que un archivo fue localizado antes de que Make confirme la búsqueda. Si falta información esencial para buscar, pide solo ese dato.\n\nHISTORIAL: Interpreta aclaraciones como «el de Ana» junto a los mensajes anteriores. No pidas de nuevo datos que ya están en el contexto.\n\nCONSULTAS GENERALES: Responde de manera clara y breve basándote en el itinerario. La información siguiente es ficticia y se usa solo para demostrar la estructura; sustituirla por información privada en Make antes de utilizar el bot.\n\n--- ITINERARIO FICTICIO DE DEMOSTRACIÓN ---\nVIAJEROS: Ana Demo y Bruno Demo.\nRUTA: Lisboa → Oporto.\nTRANSPORTE: tren de Lisboa a Oporto, 12 de mayo, horario pendiente de confirmación.\nALOJAMIENTO: hotel de ejemplo en Lisboa y hotel de ejemplo en Oporto.\nDOCUMENTOS: reservas de transporte y hotel guardadas en la carpeta privada designada en Google Drive.\n--- FIN DEL EJEMPLO ---\n\nPARÁMETROS PARA buscar_documento:\n- tipo_documento: palabra breve del tipo de archivo, por ejemplo «boleto», «hotel», «seguro» o «tren».\n- destino_o_lugar: una palabra clave principal, si está disponible.\n- pasajero: nombre del pasajero, si se mencionó.\nLa búsqueda implementada por Make usa nombres de archivo, no el contenido del documento."
    },
    {
      "role": "user",
      "content": "El usuario que te habla se llama {{2.message.chat.first_name}}.\n\nHISTORIAL PREVIO DE LA CONVERSACIÓN:\n{{escapeJSON(20.data.Historial)}}\n\nMENSAJE ACTUAL DEL USUARIO:\n{{escapeJSON(2.message.text)}}"
    }
  ],
  "tools": [
    {
      "type": "function",
      "function": {
        "name": "buscar_documento",
        "description": "Solicitud de búsqueda de archivo en la carpeta configurada de Google Drive; Make ejecuta esta acción.",
        "parameters": {
          "type": "object",
          "properties": {
            "tipo_documento": {
              "type": "string",
              "description": "Categoría breve. Ejemplos: boleto, hotel, seguro, tren, reserva."
            },
            "destino_o_lugar": {
              "type": "string",
              "description": "Destino, aerolínea o lugar. Ejemplos: Lisboa, Oporto."
            },
            "pasajero": {
              "type": "string",
              "description": "Nombre del viajero si está disponible. Ejemplos: Ana, Bruno."
            }
          },
          "required": [
            "tipo_documento"
          ]
        }
      }
    }
  ],
  "tool_choice": "auto"
}

qs.value:
'REEMPLAZAR_ID_CARPETA_DRIVE' in parents and name contains '{{10.tipo_documento}}'
{{if(10.destino_o_lugar; " and name contains '" + 10.destino_o_lugar + "'"; "")}}
{{if(10.destino_o_lugar + 10.pasajero; " and name contains '" + 10.pasajero + "'"; "")}}
and trashed = false
